import React, { useState, useEffect } from "react";
import logo from "./../../Assets/logo.png";
import "./Navbar.css";
import { useNavigate, useLocation } from "react-router-dom";
import { FaBars, FaTimes } from "react-icons/fa";

function NavBar() {
  const [isMobile, setIsMobile] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();
  const [currentPage, setCurrentPage] = useState("/");

  const scrollToTop = () => {
    window.scrollTo({
      top: 0,
      behavior: 'smooth'
    });
  };

  // Gestion du scroll pour l'effet de background
  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 10) {
        setIsScrolled(true);
      } else {
        setIsScrolled(false);
      }
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Mise à jour de la page actuelle
  useEffect(() => {
    localStorage.setItem("current", currentPage);
  }, [currentPage]);

  useEffect(() => {
    const currentPath = location.pathname;
    setCurrentPage(getPageNameFromPath(currentPath));
  }, [location]);

  // Gestion du resize pour mobile
  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth >= 768) {
        setIsMobile(false);
      }
    };

    window.addEventListener("resize", handleResize);
    return () => {
      window.removeEventListener("resize", handleResize);
    };
  }, []);

  const getPageNameFromPath = (path) => {
    const pageName = path.substring(1);
    return pageName || "/";
  };

  const handleNavigation = (path, pageName) => {
    navigate(path);
    setCurrentPage(pageName);
    scrollToTop();
    setIsMobile(false); // Fermer le menu mobile
  };

  const toggleMobileMenu = () => {
    setIsMobile(!isMobile);
  };

  return (
    <header className={`navbar-container ${isScrolled ? 'scrolled' : ''}`}>
      <nav className="navbar">
        {/* Logo */}
        <div className="navbar-logo">
          <img
            src={logo}
            alt="BIG DAY Logo"
            onClick={() => handleNavigation("/", "/")}
          />
        </div>

        {/* Navigation Desktop */}
        <ul className={`navbar-links ${isMobile ? 'mobile-active' : ''}`}>
          <li>
            <a
              href="#"
              className={currentPage === "/" ? "active" : ""}
              onClick={(e) => {
                e.preventDefault();
                handleNavigation("/", "/");
              }}
            >
              Accueil
            </a>
          </li>

          {/* Dropdown À Propos */}
          <li 
            className="dropdown"
            onMouseEnter={() => setIsDropdownOpen(true)}
            onMouseLeave={() => setIsDropdownOpen(false)}
          >
            <a
              href="#"
              className={currentPage === "program" ? "active" : ""}
              onClick={(e) => {
                e.preventDefault();
                handleNavigation("/program", "program");
              }}
            >
              À propos
            </a>
            {isDropdownOpen && (
              <ul className="dropdown-menu">
                <li>
                  <a
                    href="#"
                    onClick={(e) => {
                      e.preventDefault();
                      handleNavigation("/program?section=Theme", "program");
                    }}
                  >
                    Thème
                  </a>
                </li>
                <li>
                  <a
                    href="#"
                    onClick={(e) => {
                      e.preventDefault();
                      handleNavigation("/program?section=Panels", "program");
                    }}
                  >
                    Panels
                  </a>
                </li>
                <li>
                  <a
                    href="#"
                    onClick={(e) => {
                      e.preventDefault();
                      handleNavigation("/program?section=Workshops", "program");
                    }}
                  >
                    Workshops
                  </a>
                </li>
              </ul>
            )}
          </li>

          <li>
            <a
              href="#"
              className={currentPage === "collaboration" ? "active" : ""}
              onClick={(e) => {
                e.preventDefault();
                handleNavigation("/collaboration", "collaboration");
              }}
            >
              Collaboration
            </a>
          </li>

          <li>
            <a
              href="#"
              className={currentPage === "programme" ? "active" : ""}
              onClick={(e) => {
                e.preventDefault();
                handleNavigation("/programme", "programme");
              }}
            >
              Programme
            </a>
          </li>

          {/* Dropdown Legacy */}
          <li className="dropdown legacy-dropdown">
            <a
              href="#"
              className={currentPage === "glance" ? "active" : ""}
              onClick={(e) => {
                e.preventDefault();
                handleNavigation("/glance", "glance");
              }}
            >
              Legacy
            </a>
            <ul className="dropdown-menu">
              <li>
                <a
                  href="#"
                  onClick={(e) => {
                    e.preventDefault();
                    handleNavigation("/edition1", "glance");
                  }}
                >
                  1ère édition
                </a>
              </li>
              <li>
                <a
                  href="#"
                  onClick={(e) => {
                    e.preventDefault();
                    handleNavigation("/edition2", "glance");
                  }}
                >
                  2ème édition
                </a>
              </li>
            </ul>
          </li>

          <li>
            <a
              href="#"
              className={currentPage === "contact" ? "active" : ""}
              onClick={(e) => {
                e.preventDefault();
                handleNavigation("/contact", "contact");
              }}
            >
              Contact
            </a>
          </li>

          {/* Bouton Inscription dans le menu mobile */}
          <li className="mobile-inscription">
            <a
              href="#"
              className="inscription-button"
              onClick={(e) => {
                e.preventDefault();
                handleNavigation("/Register", "Register");
              }}
            >
              Inscription
            </a>
          </li>
        </ul>

        {/* Bouton Inscription Desktop */}
        <div className="navbar-action">
          <a
            href="#"
            className="inscription-button"
            onClick={(e) => {
              e.preventDefault();
              handleNavigation("/Register", "Register");
            }}
          >
            Inscription
          </a>
        </div>

        {/* Bouton Hamburger */}
        <button className="mobile-toggle" onClick={toggleMobileMenu}>
          {isMobile ? <FaTimes /> : <FaBars />}
        </button>
      </nav>
    </header>
  );
}

export default NavBar;
